# Curated CLI flag references injected into the planner prompt.
# Generated by scripts/llmify_engine_docs.py; checked into the repo.
_ENGINE_DOCS_DIR = Path(__file__).resolve().parents[3] / "engine-docs"
_CURATED_DOCS = {
    EngineType.VLLM: _ENGINE_DOCS_DIR / "vllm" / "cli_params.curated.md",
    EngineType.SGLANG: _ENGINE_DOCS_DIR / "sglang" / "cli_params.curated.md",
}


@lru_cache(maxsize=4)
def _load_curated_docs(engine: EngineType) -> str:
    """Load the curated CLI-flag reference for the given engine, or return empty
    string if missing (e.g., docs not regenerated)."""
    path = _CURATED_DOCS.get(engine)
    if path is None or not path.exists():
        logger.warning("Curated docs missing for %s at %s", engine.value, path)
        return ""
    return path.read_text(encoding="utf-8")

